import org.audiveris.omr.sheet.Book;
import java.nio.file.*;import java.util.*;import java.lang.reflect.*;
public class RealTupletStagesImageProbe extends RealTupletFactoryImageProbe {
 private final Object actualBook;
 static String stage="SYMBOLS";
 static final java.util.List<Object> events=new ArrayList<>(),errors=new ArrayList<>();
 static final Map<Object,java.util.List<Object>> heldTuplets=new IdentityHashMap<>(),heldChords=new IdentityHashMap<>();
 public RealTupletStagesImageProbe(Book b,SortedSet<Integer> ids){super(b,ids);actualBook=b;}
 static Object clocks(Object sys)throws Exception{java.util.List<Object> chords=new ArrayList<>(),stacks=new ArrayList<>();for(Object c:heldChords.get(sys)){Object v=field(c,"voice"),s=field(c,"slot");chords.add(map("id",id(c),"object",label(c),"voice",id(v),"voice_object",label(v),"slot",id(s),"slot_object",label(s),"time_offset",clock(c,"timeOffset"),"measure",owner(sys,call(c,"getMeasure")),"removed",call(c,"isRemoved")));}for(Object s:(java.util.List<?>)call(sys,"getStacks"))stacks.add(map("owner",stackRef(sys,s),"expected_duration",clock(s,"expectedDuration")));return map("chords",chords,"stacks",stacks);}
 static Object retained(Object sys)throws Exception{java.util.List<Object> out=new ArrayList<>();Object sig=call(sys,"getSig");for(Object t:heldTuplets.get(sys)){@SuppressWarnings("unchecked") Map<String,Object> row=(Map<String,Object>)readTuplet(sys,t);row.put("removed",call(t,"isRemoved"));row.put("in_actual_SIG",containsIdentity((Collection<?>)call(sig,"vertexSet"),t));row.put("sig_reference_retained",call(t,"getSig")==sig);row.put("contextual_grade",call(t,"getContextualGrade"));out.add(row);}return out;}
 static Object fullFrame(Object sys,String name)throws Exception{return map("system",id(sys),"stage",name,"live",tupletFrame(sys,name),"retained_tuplets",retained(sys),"clocks",clocks(sys));}
 static void listen(Object sys)throws Exception{Object sig=call(sys,"getSig");Class<?> listener=Class.forName("org.jgrapht.event.GraphListener");Object proxy=Proxy.newProxyInstance(listener.getClassLoader(),new Class<?>[]{listener},(self,method,args)->{
  if(method.getDeclaringClass()==Object.class)return switch(method.getName()){case "hashCode"->System.identityHashCode(self);case "equals"->self==args[0];default->"TupletObservationListener";};
  try{String name=method.getName();Object event=args[0];Object source=null,target=null,edge=null,vertex=null;
   if(name.startsWith("edge")){source=call(event,"getEdgeSource");target=call(event,"getEdgeTarget");edge=call(event,"getEdge");if(!containsIdentity(heldTuplets.get(sys),source)&&!containsIdentity(heldTuplets.get(sys),target))return null;}
   else{vertex=call(event,"getVertex");if(!containsIdentity(heldTuplets.get(sys),vertex))return null;}
   java.util.List<Object> trace=new ArrayList<>();for(StackTraceElement x:Thread.currentThread().getStackTrace())if(x.getClassName().startsWith("org.audiveris.omr."))trace.add(map("class",x.getClassName(),"method",x.getMethodName(),"line",x.getLineNumber()));
   Map<String,Object> row=map("order",events.size()+1,"stage",stage,"system",id(sys),"event",name,"vertex",id(vertex),"vertex_object",label(vertex),"source",id(source),"source_object",label(source),"target",id(target),"target_object",label(target),"relation_object",label(edge),"relation_kind",edge==null?null:edge.getClass().getSimpleName(),"relation_manual",edge==null?null:call(edge,"isManual"),"source_call_stack",trace,"retained_tuplets",retained(sys),"clocks",clocks(sys));
   if(edge!=null&&edge.getClass().getSimpleName().equals("ChordTupletRelation"))row.put("relation_grade",call(edge,"getGrade"));events.add(row);
  }catch(Exception e){errors.add(map("stage",stage,"event",method.getName(),"exception",e.toString()));}return null;});call(sig,"addGraphListener",proxy);}
 public void process(){try{Object stub=((java.util.List<?>)call(actualBook,"getStubs")).get(0);call(stub,"reachStep",c("step.OmrStep").getField("SYMBOLS").get(null),false);Object sheet=call(stub,"getSheet");java.util.List<?> systems=(java.util.List<?>)call(sheet,"getSystems");java.util.List<Object> frames=new ArrayList<>();for(Object sys:systems){heldTuplets.put(sys,new ArrayList<>((Collection<?>)call(call(sys,"getSig"),"inters",c("sig.inter.TupletInter"))));heldChords.put(sys,new ArrayList<>((Collection<?>)call(call(sys,"getSig"),"inters",c("sig.inter.AbstractChordInter"))));frames.add(fullFrame(sys,"after_ordinary_SYMBOLS"));listen(sys);}for(String next:java.util.List.of("LINKS","RHYTHMS")){stage=next;call(stub,"reachStep",c("step.OmrStep").getField(next).get(null),false);for(Object sys:systems)frames.add(fullFrame(sys,"after_ordinary_"+next));}Files.writeString(Path.of(System.getProperty("native.probe.output")),json(map("scope","Separate fresh ordinary original image run: reachStep(SYMBOLS), then same stub reachStep(LINKS), then reachStep(RHYTHMS), preserving source step bookkeeping and avoiding repeated Symbols. GraphListener observes only previously held actual Tuplet objects and related edges.","instrumentation","Listener registered after existing SIG listener, so graph events observe original callback aftermath. Raw chord/stack clock fields are read without erasure or synthetic reconstruction. Removal call stacks identify executed original method. Earlier factory probe remains a separate observation, not the same Java owner instance.","native_outputs_used",false,"frames",frames,"events",events,"observer_errors",errors))+"\n");if(!errors.isEmpty())throw new Exception("observer errors");}catch(Exception e){throw new RuntimeException(e);}}
}
